package com.tienda.products.dto;

import com.tienda.products.entity.Product;

import java.math.BigDecimal;

/**
 * OUTPUT DTO: ProductResponse.
 *
 * <p>This is what the API returns to the frontend. It is built from the entity
 * through the static factory method {@link #from(Product)}.
 *
 * <p>Why not return the entity directly: this way the shape of the JSON response
 * stays under the control of the API and does not change with internal entity changes.
 */
public class ProductResponse {

    /** Product identifier (already generated by PostgreSQL). */
    private Long id;

    /** Product name. */
    private String name;

    /** Product description. */
    private String description;

    /** Product price. */
    private BigDecimal price;

    /** Empty constructor: Jackson needs it to deserialise. */
    public ProductResponse() {
    }

    /**
     * Constructor with every field.
     */
    public ProductResponse(Long id, String name, String description, BigDecimal price) {
        this.id = id;
        this.name = name;
        this.description = description;
        this.price = price;
    }

    /**
     * Factory method: converts a Product entity into a ProductResponse.
     *
     * <p>It is the "translator" between the world of the database and the world of the API.
     */
    public static ProductResponse from(Product product) {
        return new ProductResponse(
                product.getId(),
                product.getName(),
                product.getDescription(),
                product.getPrice()
        );
    }

    /** Returns the product id. */
    public Long getId() {
        return id;
    }

    /** Sets the product id. */
    public void setId(Long id) {
        this.id = id;
    }

    /** Returns the product name. */
    public String getName() {
        return name;
    }

    /** Sets the product name. */
    public void setName(String name) {
        this.name = name;
    }

    /** Returns the product description. */
    public String getDescription() {
        return description;
    }

    /** Sets the product description. */
    public void setDescription(String description) {
        this.description = description;
    }

    /** Returns the product price. */
    public BigDecimal getPrice() {
        return price;
    }

    /** Sets the product price. */
    public void setPrice(BigDecimal price) {
        this.price = price;
    }
}
